export function toposort(nodes, edges) {
  if (!Array.isArray(nodes)) throw new TypeError('nodes must be an array');
  if (!Array.isArray(edges)) throw new TypeError('edges must be an array');

  const seen = new Set();
  for (const name of nodes) {
    if (typeof name !== 'string') throw new TypeError('a node name must be a string');
    if (seen.has(name)) throw new TypeError('a node name appears twice');
    seen.add(name);
  }

  const blockedBy = new Map();
  for (const name of nodes) blockedBy.set(name, []);

  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) {
      throw new TypeError('an edge must be an array of two strings');
    }
    if (typeof edge[0] !== 'string' || typeof edge[1] !== 'string') {
      throw new TypeError('an edge must be an array of two strings');
    }
    if (!seen.has(edge[0]) || !seen.has(edge[1])) {
      throw new RangeError('an edge names a node that is not listed');
    }
    blockedBy.get(edge[1]).push(edge[0]);
  }

  const done = new Set();
  const order = [];
  while (order.length < nodes.length) {
    let chosen = null;
    for (const name of nodes) {
      if (done.has(name)) continue;
      if (blockedBy.get(name).every((before) => done.has(before))) {
        chosen = name;
        break;
      }
    }
    if (chosen === null) throw new Error('the edges make a cycle');
    done.add(chosen);
    order.push(chosen);
  }
  return order;
}
